#!/bin/zsh
# QA of the data flow for the given dates: Bronze -> DQ -> Silver -> positions -> entities -> report records -> lineage -> validation -> 6G XML.
# Every query returns ONLY defect rows; an empty result is a pass.
set -a; . "$(cd "$(dirname "$0")/../.." && pwd)/.env"; set +a   # settings: the repo's .env (see .env.example)
C=$FR2052A_CATALOG
D=${1:-"'2026-02-23','2026-02-24','2026-02-25','2026-02-26','2026-02-27'"}
run(){ echo "== $1"; bash "$(dirname "$0")/q.sh" "$2" | tail -n +2 | sed 's/^/   DEFECT /'; }
run "Q01 Bronze = feed monitor = Silver + quarantine (per feed)" "
WITH b AS (SELECT 'deposits' f, as_of_date d, count(*) n FROM $C.raw.deposits GROUP BY 2 UNION ALL SELECT 'derivatives', as_of_date, count(*) FROM $C.raw.derivatives GROUP BY 2
 UNION ALL SELECT 'finance', as_of_date, count(*) FROM $C.raw.finance GROUP BY 2 UNION ALL SELECT 'funding', as_of_date, count(*) FROM $C.raw.funding GROUP BY 2
 UNION ALL SELECT 'loans', as_of_date, count(*) FROM $C.raw.loans GROUP BY 2 UNION ALL SELECT 'securities', as_of_date, count(*) FROM $C.raw.securities GROUP BY 2),
s AS (SELECT source_feed f, as_of_date d, count(*) n FROM $C.conformed.source_position GROUP BY 1,2),
q AS (SELECT source_feed f, as_of_date d, count(*) n FROM $C.dq.quarantine GROUP BY 1,2),
m AS (SELECT feed f, as_of_date d, records n FROM $C.dq.feed_monitor)
SELECT b.d, b.f, b.n bronze, m.n monitor, s.n silver, coalesce(q.n,0) quar FROM b LEFT JOIN s USING (f,d) LEFT JOIN q USING (f,d) LEFT JOIN m USING (f,d)
WHERE b.d IN ($D) AND (b.n<>coalesce(m.n,-1) OR b.n - coalesce(s.n,0) - coalesce(q.n,0)<>0)"
run "Q02 every quarantined record has its rule rows (DQ queue source)" "SELECT q.as_of_date, q.record_id FROM $C.dq.quarantine q LEFT ANTI JOIN $C.dq.rule_failures r ON r.as_of_date=q.as_of_date AND r.record_id=q.record_id WHERE q.as_of_date IN ($D)"
run "Q03 DQ assessment failed_records = quarantined + warned records" "SELECT a.as_of_date, a.rule_id, a.failed_records, count(r.record_id) rows FROM $C.dq.assessment_results a LEFT JOIN $C.dq.rule_failures r ON r.as_of_date=a.as_of_date AND r.rule_id=a.rule_id WHERE a.as_of_date IN ($D) GROUP BY 1,2,3 HAVING a.failed_records<>count(r.record_id)"
run "Q04 Silver record without a position and not held out" "SELECT s.as_of_date, s.record_id FROM $C.conformed.source_position s LEFT ANTI JOIN $C.conformed.fact_liquidity_position f ON f.as_of_date=s.as_of_date AND f.record_id=s.record_id WHERE s.as_of_date IN ($D) AND s.record_id NOT IN (SELECT record_id FROM $C.dq.pid_exceptions e WHERE e.as_of_date=s.as_of_date)"
run "Q05 principal: Silver = positions + held out (per feed)" "SELECT s.as_of_date, s.source_feed, round(sum(s.principal_amount),2) silver, round(sum(coalesce(f.p,0)) + sum(CASE WHEN f.p IS NULL AND e.record_id IS NOT NULL THEN s.principal_amount ELSE 0 END),2) pos_plus_held FROM $C.conformed.source_position s LEFT JOIN (SELECT as_of_date, record_id, sum(principal_amount) p FROM $C.conformed.fact_liquidity_position GROUP BY 1,2) f ON f.as_of_date=s.as_of_date AND f.record_id=s.record_id LEFT JOIN (SELECT DISTINCT as_of_date, record_id FROM $C.dq.pid_exceptions) e ON e.as_of_date=s.as_of_date AND e.record_id=s.record_id WHERE s.as_of_date IN ($D) GROUP BY 1,2 HAVING abs(coalesce(sum(s.principal_amount),0) - sum(coalesce(f.p,0)) - sum(CASE WHEN f.p IS NULL AND e.record_id IS NOT NULL THEN s.principal_amount ELSE 0 END)) > 0.01"
run "Q06 duplicate position / record key" "SELECT 'position' k, as_of_date, position_id FROM $C.conformed.fact_liquidity_position WHERE as_of_date IN ($D) GROUP BY 1,2,3 HAVING count(*)>1 UNION ALL SELECT 'record_key', as_of_date, record_key FROM $C.reg_2052a.v_filing_records WHERE as_of_date IN ($D) GROUP BY 1,2,3 HAVING count(*)>1"
run "Q07 position with a PID but in no reporting entity / without a PID" "SELECT f.as_of_date, f.position_id, f.product_id FROM $C.conformed.fact_liquidity_position f LEFT ANTI JOIN $C.conformed.entity_position e ON e.as_of_date=f.as_of_date AND e.position_id=f.position_id WHERE f.as_of_date IN ($D) UNION ALL SELECT as_of_date, position_id, 'NO PID' FROM $C.conformed.fact_liquidity_position WHERE as_of_date IN ($D) AND product_id IS NULL"
run "Q08 entity position not in any reported record (lineage)" "SELECT e.as_of_date, e.reporting_entity, e.position_id FROM $C.conformed.entity_position e LEFT ANTI JOIN $C.reg_2052a.record_lineage l ON l.as_of_date=e.as_of_date AND l.position_id=e.position_id AND l.reporting_entity=e.reporting_entity WHERE e.as_of_date IN ($D)"
run "Q09 reported record: lineage count / amount mismatch (S.L.6 LCR ratio is computed, excluded)" "
WITH r AS (SELECT * FROM $C.reg_2052a.v_filing_records WHERE as_of_date IN ($D) AND product_id <> 'S.L.6'),
l AS (SELECT as_of_date, record_key, count(*) n, sum(amount) a FROM $C.reg_2052a.record_lineage WHERE as_of_date IN ($D) GROUP BY 1,2)
SELECT r.as_of_date, r.table_code, r.record_key, r.record_count, l.n, r.reported_amount, l.a FROM r LEFT JOIN l USING (as_of_date, record_key) WHERE l.n IS NULL OR r.record_count<>l.n OR abs(r.reported_amount-l.a)>0.01"
run "Q10 S.L.6 = LCR engine; LCR recon / GL recon breaks" "SELECT r.as_of_date, r.reporting_entity, r.reported_amount, c.lcr_ratio FROM $C.reg_2052a.v_filing_records r JOIN $C.reg_lcr.calculation_results c ON c.as_of_date=r.as_of_date AND c.entity_id=r.reporting_entity WHERE r.product_id='S.L.6' AND r.as_of_date IN ($D) AND abs(r.reported_amount-round(c.lcr_ratio,4))>0.0001 UNION ALL SELECT as_of_date, entity_id, metric_name, status FROM $C.audit.cross_metric_recon WHERE as_of_date IN ($D) AND status<>'PASS'"
run "Q11 GL break not surfaced as RECON-GL rule" "SELECT g.as_of_date, count(*) breaks, max(v.records_failed) rule_failed FROM $C.audit.gl_reconciliation g LEFT JOIN $C.reg_2052a.gold_validation v ON v.as_of_date=g.as_of_date AND v.rule_id='RECON-GL' WHERE g.as_of_date IN ($D) AND g.status<>'PASS' GROUP BY 1 HAVING count(*)<>coalesce(max(v.records_failed),-1)"
run "Q12 rule records_failed <> detail rows" "SELECT v.as_of_date, v.rule_id, sum(v.records_failed) rf, max(d.n) det FROM $C.reg_2052a.gold_validation v LEFT JOIN (SELECT as_of_date, rule_id, count(*) n FROM $C.reg_2052a.gold_validation_detail GROUP BY 1,2) d USING (as_of_date, rule_id) WHERE v.as_of_date IN ($D) AND v.status IN ('FAIL','WARNING') GROUP BY 1,2 HAVING sum(v.records_failed) <> coalesce(max(d.n),0) AND sum(v.records_failed) <= 500"
run "Q13 latest run: file record counts = report records; XSD; release status vs ERROR fails" "
WITH lr AS (SELECT as_of_date, max(run_number) rn FROM $C.reg_2052a.submission_files WHERE as_of_date IN ($D) GROUP BY 1),
f AS (SELECT s.as_of_date, sum(CASE WHEN file_type IN ('Primary','Reduced') THEN record_count ELSE 0 END) recs, bool_and(xsd_valid) xsd, max(release_status) rs FROM $C.reg_2052a.submission_files s JOIN lr ON lr.as_of_date=s.as_of_date AND lr.rn=s.run_number GROUP BY 1),
r AS (SELECT as_of_date, count(*) n FROM $C.reg_2052a.v_filing_records WHERE as_of_date IN ($D) GROUP BY 1),
e AS (SELECT as_of_date, count_if(status='FAIL' AND severity='ERROR') errs FROM $C.reg_2052a.gold_validation WHERE as_of_date IN ($D) GROUP BY 1)
SELECT f.*, r.n, e.errs FROM f JOIN r USING (as_of_date) JOIN e USING (as_of_date) WHERE f.recs<>r.n OR NOT f.xsd OR (e.errs>0 AND f.rs NOT IN ('BLOCKED')) OR (e.errs=0 AND f.rs='BLOCKED')"
run "Q14 one validation run per date (no stale rows)" "SELECT as_of_date, count(DISTINCT run_timestamp) FROM $C.reg_2052a.gold_validation WHERE as_of_date IN ($D) GROUP BY 1 HAVING count(DISTINCT run_timestamp)>1"
